//! Renders the TypeScript bindings for every Rust type that crosses into the UI.
#![forbid(unsafe_code)]

use specta::Types;
use specta_typescript::Typescript;

/// Path of the generated file, relative to the repository root.
pub const OUTPUT: &str = "packages/wf-wasm/src/bindings.ts";

/// First line of the generated file.
pub const HEADER: &str =
    "// Generated by crates/wf-bindings from the Rust types. Do not edit; run `npm run bindings`.";

/// Failure while rendering or writing the bindings.
#[derive(Debug, thiserror::Error)]
pub enum BindingsError {
    /// specta could not express a type in TypeScript.
    #[error("export failed: {0}")]
    Export(#[from] specta_typescript::Error),
    /// Reading or writing the output file failed.
    #[error("io on {path}: {source}")]
    Io {
        /// File that failed.
        path: std::path::PathBuf,
        /// Underlying error.
        source: std::io::Error,
    },
}

/// Every type exported to TypeScript. Add new types here.
#[must_use]
